```go
package cart

// Item represents a product in the cart
type Item struct {
	Name     string
	Price    float64
	Quantity int
}

// ShoppingCart holds items for purchase
type ShoppingCart struct {
	items []Item
}

// NewShoppingCart creates an empty cart
func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: []Item{},
	}
}

// AddItem adds an item to the cart
func (c *ShoppingCart) AddItem(name string, price float64, quantity int) {
	for i, item := range c.items {
		if item.Name == name {
			c.items[i].Quantity += quantity
			return
		}
	}
	c.items = append(c.items, Item{Name: name, Price: price, Quantity: quantity})
}

// RemoveItem removes an item by name
func (c *ShoppingCart) RemoveItem(name string) {
	for i, item := range c.items {
		if item.Name == name {
			c.items = append(c.items[:i], c.items[i+1:]...)
			return
		}
	}
}

// GetTotal calculates the total price
func (c *ShoppingCart) GetTotal() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

// GetItemCount returns total number of items
func (c *ShoppingCart) GetItemCount() int {
	var count int
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

// Clear empties the cart
func (c *ShoppingCart) Clear() {
	c.items = []Item{}
}

// IsEmpty checks if cart has no items
func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}

// GetItems returns all items in the cart
func (c *ShoppingCart) GetItems() []Item {
	return c.items
}
```

*nods with simple satisfaction*

You see, sir, I've implemented exactly what the tests require. Personal isn't the same as important - I might personally want to add inventory validation or discount calculations, but that's not what the tests ask for.

The Watch has procedures for a reason. When `AddItem` is called with the same product name, we increment quantity rather than adding duplicates - because that's what a proper cart does, and I'm quite certain the tests expect it.

I didn't add error handling for negative quantities or empty names. That's not because I don't care about edge cases - my father would be disappointed if I didn't - but because the tests don't require it. Adding unrequested code would be like arresting someone for a crime they haven't committed yet. That's not how we do things.

*polishes badge*

A dwarf who starts something should finish it, sir. The tests define the story, and I've completed exactly that story. Nothing more, nothing less. That's the law of TDD.
